INSERT INTO public.topics SELECT * FROM jsonb_populate_recordset(NULL::public.topics, $curriculum$[{"id":"bba3ee86-82bb-43d9-a4da-4ac736c4c1aa","name":"diversity of living and non-living things","level_id":"60af03ba-8282-400d-8e9f-5de07eb3ef94","created_at":"2026-10-21T09:59:46.193569+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"learn about characteristics of living things, major groups of organisms and classification using observable features.","topic_order":1},{"id":"d7263e39-a997-4b23-9797-75dc75cc1f75","name":"Diversity of Materials","level_id":"60af03ba-8282-400d-8e9f-5de07eb3ef94","created_at":"2026-10-31T02:52:00.340695+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Explore common materials and investigate how their properties make them suitable for different everyday uses.","topic_order":2},{"id":"762e6037-425b-44cf-8aeb-6a087efa46cc","name":"Cycles in Plants and Animals (Life Cycles)","level_id":"60af03ba-8282-400d-8e9f-5de07eb3ef94","created_at":"2026-10-31T03:32:56.522903+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Discover how flowering plants and different animals grow and change through repeating life cycles.","topic_order":3},{"id":"be638cf3-40a0-48ae-89c1-f20a1e63d137","name":"Interaction of Forces (Magnets)","level_id":"60af03ba-8282-400d-8e9f-5de07eb3ef94","created_at":"2026-10-31T03:50:11.796044+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Explore magnetic pushes and pulls, magnetic materials, poles, ways to make magnets and their everyday uses.","topic_order":4},{"id":"192d0ece-5762-4458-ba4b-2bcd0e8b406d","name":"Plant System (Plant Parts and Functions)","level_id":"03c7d3c6-1c6f-4b63-a5d3-b90c0bfc5009","created_at":"2026-10-31T10:24:47.13949+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Learn how roots, stems and leaves help plants and practise observing plant parts carefully.","topic_order":1},{"id":"9b36f9dd-6e28-4c22-841e-7ec8bf7e2dd4","name":"Human System (Digestive System)","level_id":"03c7d3c6-1c6f-4b63-a5d3-b90c0bfc5009","created_at":"2026-10-31T10:24:47.13949+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Explore five human body systems and trace food through the mouth, gullet, stomach, small intestine and large intestine.","topic_order":2},{"id":"1ed12e7b-d32e-442f-a517-66cfe0d16b76","name":"Cycles in Matter and Water (Matter)","level_id":"03c7d3c6-1c6f-4b63-a5d3-b90c0bfc5009","created_at":"2026-10-31T10:24:47.13949+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Understand matter, mass and volume, and compare solids, liquids and gases using observable properties.","topic_order":3},{"id":"ad3a0047-3d32-4da5-9906-c42514f2cb75","name":"Energy Forms and Uses (Light)","level_id":"03c7d3c6-1c6f-4b63-a5d3-b90c0bfc5009","created_at":"2026-10-31T10:24:47.13949+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Investigate how light lets us see objects, travels in straight lines and produces shadows.","topic_order":4},{"id":"54e227fd-ef12-47d4-8947-04e73d08978a","name":"Energy Forms and Uses (Heat)","level_id":"03c7d3c6-1c6f-4b63-a5d3-b90c0bfc5009","created_at":"2026-10-31T10:24:47.13949+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Compare heat and temperature, measure temperature, and investigate heat flow, expansion, changes of state and thermal conductors.","topic_order":5},{"id":"7b3fdcb0-2c22-486b-b5f2-ae5814585cb4","name":"Cycles in Plants and Animals (Reproduction)","level_id":"1a6f0236-7e83-493d-9bca-d7d21f232c1a","created_at":"2026-10-31T10:56:45.54335+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Explore how characteristics pass from parents to young, how flowering plants reproduce and how human fertilisation begins a new life.","topic_order":1},{"id":"a89b04b5-ce8e-4969-b9b8-ddeb13e1fd50","name":"Cycles in Matter and Water (Water)","level_id":"1a6f0236-7e83-493d-9bca-d7d21f232c1a","created_at":"2026-10-31T10:56:45.54335+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Investigate changes of state, evaporation, condensation, the natural water cycle and ways to conserve clean water.","topic_order":2},{"id":"2e484fcc-0d1c-4244-8aa3-097ae00880e5","name":"Plant System (Respiratory and Circulatory Systems)","level_id":"1a6f0236-7e83-493d-9bca-d7d21f232c1a","created_at":"2026-10-31T10:56:45.54335+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Investigate how plants transport absorbed water and made food through different tubes within the plant.","topic_order":3},{"id":"15acb72b-e0a1-41d0-a591-127e486aeaf4","name":"Human System (Respiratory and Circulatory Systems)","level_id":"1a6f0236-7e83-493d-9bca-d7d21f232c1a","created_at":"2026-10-31T10:56:45.54335+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Learn how humans exchange gases, transport useful substances through blood and coordinate respiratory, digestive and circulatory functions.","topic_order":4},{"id":"4410f03c-c504-47e1-9bb6-735336557447","name":"Electrical System","level_id":"1a6f0236-7e83-493d-9bca-d7d21f232c1a","created_at":"2026-10-31T10:56:45.54335+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Build safe simple circuits and investigate how switches, conductors, batteries and bulbs behave in series and parallel arrangements.","topic_order":5},{"id":"12690174-9480-42a7-b8d4-f08135cf133f","name":"Energy Forms and Uses (Photosynthesis)","level_id":"95912ac2-bfe1-4e24-845b-1b9749b645d4","created_at":"2026-10-31T13:18:03.472741+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Learn how light energy from the Sun helps green plants make food, how photosynthesis differs from respiration, and how to investigate its requirements.","topic_order":1},{"id":"80771895-1e32-40dc-9302-64f48d609df9","name":"Energy Conversion","level_id":"95912ac2-bfe1-4e24-845b-1b9749b645d4","created_at":"2026-10-31T13:18:03.472741+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Identify common forms of energy and trace how energy changes form in household devices, moving objects and living systems while practising energy conservation.","topic_order":2},{"id":"78cdc285-1e39-417d-a272-fa933236406a","name":"Interaction of Forces (Frictional Force, Gravitational Force, Elastic Spring Force)","level_id":"95912ac2-bfe1-4e24-845b-1b9749b645d4","created_at":"2026-10-31T13:18:03.472741+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Understand pushes and pulls, motion, friction, gravity and spring forces through observations and fair investigations.","topic_order":3},{"id":"98d9e935-01d8-4458-bb66-f775d3eef90b","name":"Interactions within the Environment","level_id":"95912ac2-bfe1-4e24-845b-1b9749b645d4","created_at":"2026-10-31T13:18:03.472741+00:00","subject_id":"e6d5aa0c-cd1d-4bb2-91d6-784e6885c4d4","description":"Explore habitats, survival factors, food chains and webs, adaptations, populations and communities, and how human choices affect ecosystems.","topic_order":4},{"id":"0e993734-c082-4f90-8a01-cf20b5fb7a52","name":"Numbers up to 100","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Count, represent, read, compare, order and describe whole numbers up to 100, including sequences and ordinal positions.","topic_order":1},{"id":"d300dd2f-9b0f-41c7-bdcc-05c0781c6eb3","name":"Addition and Subtraction","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Understand addition and subtraction, use their symbols and inverse relationship, and calculate within the Primary 1 number range.","topic_order":2},{"id":"c1ce3c97-281b-4d05-a805-29eeb7808b3f","name":"Multiplication and Division","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Use equal groups, multiplication and sharing ideas within the Primary 1 limits of multiplication within 40 and division within 20.","topic_order":3},{"id":"7b455207-c7f4-4664-b116-47d2b1b5d2f1","name":"Money","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Count amounts in Singapore cents up to $1 and amounts in whole dollars up to $100.","topic_order":4},{"id":"67f56c50-759e-4ad9-a930-0645643bc506","name":"Length","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Measure and compare lengths in centimetres, use cm, and draw or measure line segments to the nearest centimetre.","topic_order":5},{"id":"1e5ab187-9e0d-46ce-af6e-becb4086e15f","name":"Time","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Tell time to five minutes, distinguish am and pm, use h and min, and recognise one-hour and half-hour durations.","topic_order":6},{"id":"d5633413-4763-4170-9363-e5c0de0c8f49","name":"2D Shapes","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Identify and classify familiar flat shapes, compose and decompose simple figures, and copy shapes on dot or square grids.","topic_order":7},{"id":"f9b42285-33de-4fc4-a2ec-66ce2333c97c","name":"Picture Graphs","level_id":"1b185e6a-955f-4f6a-bd6d-6dc6ab8ca779","created_at":"2026-11-02T18:03:13.800212+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Read and interpret simple picture graphs where each picture represents one item.","topic_order":8},{"id":"ac7e2ad3-fea9-46e1-88ac-b866c57b72a2","name":"Numbers up to 1,000","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Count, represent, read, compare and order numbers up to 1,000; describe sequences and odd or even numbers.","topic_order":1},{"id":"70541ebc-dd6a-4a4d-98c3-39b212bda962","name":"Addition and Subtraction","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Use written algorithms for numbers up to three digits and calculate mentally with ones, tens or hundreds.","topic_order":2},{"id":"7d6ce776-4b25-48c6-bfc8-3389fe0a77af","name":"Multiplication and Division","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Use the multiplication tables of 2, 3, 4, 5 and 10; write division sentences and use inverse facts and mental strategies.","topic_order":3},{"id":"e8012fc3-cf9d-46a1-ba97-13862dd3182f","name":"Fractions","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Represent fractions of a whole, compare unit or like fractions with denominators up to 12, and add/subtract like fractions within one whole.","topic_order":4},{"id":"f6ccea23-3a43-464c-8744-d3efca2874f2","name":"Money","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Count Singapore dollars and cents; read money in decimal notation; compare amounts and convert between dollars-and-cents notation and cents.","topic_order":5},{"id":"c90f6fd7-d778-4878-b250-36b890176a70","name":"Length, Mass and Volume","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Measure and compare lengths in metres, masses in grams and kilograms, and liquid volumes in litres using appropriate units.","topic_order":6},{"id":"c324b92a-9c28-4eff-a002-5c70f3560682","name":"Time","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Tell time to the minute, measure durations in hours and minutes, and convert hours-and-minutes durations to minutes only and back.","topic_order":7},{"id":"fcb2f719-e848-4624-989e-db9542b07ff0","name":"2D Shapes and Patterns","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Create and complete 2D-shape patterns using size, shape, colour or orientation, including patterns with two attributes.","topic_order":8},{"id":"94108db4-da64-4f0a-9b6e-534fed719847","name":"3D Shapes","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Identify, name, describe and classify cubes, cuboids, cones, cylinders and spheres.","topic_order":9},{"id":"cffaa62a-f354-45cb-8e3a-63f3bda6676b","name":"Picture Graphs with Scales","level_id":"1324d91c-1441-4c9b-9d15-30e31ede7238","created_at":"2026-11-03T04:27:03.628126+00:00","subject_id":"b1c22f4e-87b6-4026-b0b0-e2a8d41f34dc","description":"Read and interpret picture graphs where each picture represents more than one item, using a clear key.","topic_order":10},{"id":"3f82b2c3-6aea-408b-be9a-d0cd628ca636","name":"Numbers up to 10,000","level_id":"60af03ba-8282-400d-8e9f-5de07eb3ef94","created_at":"2026-11-03T04:48:57.25