INSERT INTO public.question_options SELECT * FROM jsonb_populate_recordset(NULL::public.question_options, $curriculum$[{"id":"06240419-7634-4636-b3eb-9dc259f490bb","option_text":"all living things can walk.","question_id":"4452e317-6ada-411c-a4bf-280f5495b9a2","option_order":1},{"id":"ec1afab0-81a8-49cb-b893-af16296956d1","option_text":"living things need water, air and food.","question_id":"4452e317-6ada-411c-a4bf-280f5495b9a2","option_order":2},{"id":"6b4ae8a1-ae2e-41a8-b4c7-999cd162cf58","option_text":"all living things have eyes.","question_id":"4452e317-6ada-411c-a4bf-280f5495b9a2","option_order":3},{"id":"e1902596-4de1-4255-ab13-7edfe1ebabc5","option_text":"living things always move from place to place.","question_id":"4452e317-6ada-411c-a4bf-280f5495b9a2","option_order":4},{"id":"ef41f1a1-b2ef-489f-b461-cffdd6ed8134","option_text":"reproduction","question_id":"c642d742-d1a6-4529-af84-1e57ccfa39e1","option_order":1},{"id":"5c382b88-1758-4370-8b38-2643dcddc9d6","option_text":"responding to surroundings","question_id":"c642d742-d1a6-4529-af84-1e57ccfa39e1","option_order":2},{"id":"e5d00995-fb40-499c-9bfa-bf9c7075c799","option_text":"being non-living","question_id":"c642d742-d1a6-4529-af84-1e57ccfa39e1","option_order":3},{"id":"4a0895f0-9dac-42a2-8b1a-2c93694ba5a5","option_text":"producing sound","question_id":"c642d742-d1a6-4529-af84-1e57ccfa39e1","option_order":4},{"id":"d2a10b0c-1a5b-408d-b098-31ba9876ba56","option_text":"it cannot move.","question_id":"4c70c0f7-7513-4870-8d64-243d718c35fd","option_order":1},{"id":"c9777408-d96c-4001-9982-d333b5b7e95c","option_text":"it cannot make sounds.","question_id":"4c70c0f7-7513-4870-8d64-243d718c35fd","option_order":2},{"id":"a4324a21-91c6-49b3-a287-6e099caacb20","option_text":"it does not carry out the life processes of a living organism.","question_id":"4c70c0f7-7513-4870-8d64-243d718c35fd","option_order":3},{"id":"391df8d6-9d6f-465c-a18b-71db03f1710f","option_text":"it has four legs.","question_id":"4c70c0f7-7513-4870-8d64-243d718c35fd","option_order":4},{"id":"b184f9fd-4d0b-4176-95a9-f70f8764d15f","option_text":"it has become a non-flowering plant.","question_id":"d3b7eaab-df72-4281-9fdd-6907b343caab","option_order":1},{"id":"e759a616-a937-4665-a496-113ef7fbf75d","option_text":"it is still a flowering plant.","question_id":"d3b7eaab-df72-4281-9fdd-6907b343caab","option_order":2},{"id":"f1061930-3b66-4d3c-bd47-81a34e65ac8a","option_text":"it is now a fungus.","question_id":"d3b7eaab-df72-4281-9fdd-6907b343caab","option_order":3},{"id":"1f9e49aa-ea15-48a6-810e-9254a985e7e4","option_text":"it is no longer living.","question_id":"d3b7eaab-df72-4281-9fdd-6907b343caab","option_order":4},{"id":"78561918-5ab3-4edd-bcff-43f0fd9c87a1","option_text":"six legs","question_id":"2f9058b7-3938-46a0-9e90-ea625a6ff59b","option_order":1},{"id":"b0ae9d3f-416c-43bc-be8c-6ac67ad53391","option_text":"gills","question_id":"2f9058b7-3938-46a0-9e90-ea625a6ff59b","option_order":2},{"id":"d832d127-85ee-4e0c-b309-a36e75f7ab34","option_text":"feathers","question_id":"2f9058b7-3938-46a0-9e90-ea625a6ff59b","option_order":3},{"id":"cae60086-a7e3-49df-9345-34e683af17e1","option_text":"dry scales","question_id":"2f9058b7-3938-46a0-9e90-ea625a6ff59b","option_order":4},{"id":"ee491f4c-aa36-460d-b187-e02d06e46353","option_text":"fungi","question_id":"dc1722de-ebf6-4f04-9ff6-5e5408f1d0f4","option_order":1},{"id":"b436a65a-acfb-477f-9f9c-a8c0f122abe1","option_text":"bacteria","question_id":"dc1722de-ebf6-4f04-9ff6-5e5408f1d0f4","option_order":2},{"id":"eb7235e6-531f-409a-a3ff-36fe577669b0","option_text":"mammals","question_id":"dc1722de-ebf6-4f04-9ff6-5e5408f1d0f4","option_order":3},{"id":"517c1726-bc82-48a3-82ed-454543b3e38c","option_text":"flowering plants","question_id":"dc1722de-ebf6-4f04-9ff6-5e5408f1d0f4","option_order":4},{"id":"185b220a-ef24-40d7-bbef-11e5b7cb7610","option_text":"p: fish; q: bird; r: reptile","question_id":"373dfd78-5341-4add-9a2f-2a0f297f41da","option_order":1},{"id":"d965368e-a71e-4f15-bee7-57f33db8a572","option_text":"p: bird; q: insect; r: mammal","question_id":"373dfd78-5341-4add-9a2f-2a0f297f41da","option_order":2},{"id":"15fa202b-ab9d-42eb-add1-cae9d2ef9e64","option_text":"p: mammal; q: fish; r: insect","question_id":"373dfd78-5341-4add-9a2f-2a0f297f41da","option_order":3},{"id":"3d241ae5-5600-4b26-bbfe-a4591f0c077b","option_text":"p: insect; q: reptile; r: bird","question_id":"373dfd78-5341-4add-9a2f-2a0f297f41da","option_order":4},{"id":"36add409-7a4b-4c6f-b2fd-464c34844f3d","option_text":"x is non-living because it did not move at first.","question_id":"de1c3aa9-65e8-4dc5-b324-183769fce7ae","option_order":1},{"id":"05a96760-acb6-4474-bb28-1d4a6671199c","option_text":"y must be living because it moves.","question_id":"de1c3aa9-65e8-4dc5-b324-183769fce7ae","option_order":2},{"id":"53fd20d6-011e-43a2-a332-d4e2775adfcb","option_text":"x is living because it can grow, while movement alone does not make y living.","question_id":"de1c3aa9-65e8-4dc5-b324-183769fce7ae","option_order":3},{"id":"d436cef7-e375-4ef3-a2bb-3e3d27fbf058","option_text":"both objects must be living because they can change position.","question_id":"de1c3aa9-65e8-4dc5-b324-183769fce7ae","option_order":4},{"id":"ef60b8ab-deec-4490-bbef-d867485ce0ae","option_text":"p cannot be a bird because it cannot fly, and r must be non-flowering.","question_id":"557e78ef-e156-47e6-aaf5-9c6aa42a99a6","option_order":1},{"id":"344e3079-9022-4997-9497-e2c1c7caeeab","option_text":"q must be a spider because it has six legs.","question_id":"557e78ef-e156-47e6-aaf5-9c6aa42a99a6","option_order":2},{"id":"a444f7c3-d8b5-4455-b016-1027ab66e842","option_text":"p can be classified as a bird, and s belongs to the fungi group.","question_id":"557e78ef-e156-47e6-aaf5-9c6aa42a99a6","option_order":3},{"id":"0600ff83-9053-4b9f-9ded-e6d3ef42480d","option_text":"r must be non-living because it has no flowers.","question_id":"557e78ef-e156-47e6-aaf5-9c6aa42a99a6","option_order":4},{"id":"72130d54-0d1e-4703-8b88-4